mapper.insert:

declare
  v_cpam_ddi_call      call_parameters.cpam_ddi_call%type;
  v_cpam_ddn_call      call_parameters.cpam_ddn_call%type;
  v_cpam_local_call    call_parameters.cpam_local_call%type;
  v_cpam_incoming_call call_parameters.cpam_incoming_call%type;
  v_cpam_aty_id        call_parameters.cpam_aty_id%type;
  v_cpam_lty_id        call_parameters.cpam_lty_id%type;
  v_cpam_sys_code_id   call_parameters.cpam_sys_code_id%type;
begin
  select cpam_ddi_call, cpam_ddn_call, cpam_local_call, cpam_incoming_call,
         cpam_aty_id, cpam_lty_id, cpam_sys_code_id
    into v_cpam_ddi_call, v_cpam_ddn_call, v_cpam_local_call, v_cpam_incoming_call,
         v_cpam_aty_id, v_cpam_lty_id, v_cpam_sys_code_id
    from call_parameters
   where sysdate between cpam_start_date and cpam_end_date
     and rownum = 1;
  insert into prepay_cellulars
    (pce_handle, pce_clu_cellular_number, pce_pcs_id_actual, pce_pcs_id_before,
     pce_pcc_id, pce_last_status_update, pce_last_update, pce_add_date,
     pce_available_amount, pce_ddi, pce_ddn, pce_loc, pce_incoming,
     pce_anouncement, pce_prev_amount, pce_lang_id, pce_account_amount,
     pce_sys_code_id, pce_first_call_date, pce_last_call_date, pce_percentage,
     pce_due_amount_date, pce_suspend_date, pce_cancel_date, pce_expiration_date,
     pce_psa_action_status, pce_err_id)
  values
    (#{handle}, #{cellularNumber}, #{statusPpay}, #{statusPpay}, 'NM', sysdate,
     sysdate, sysdate, 0, v_cpam_ddi_call, v_cpam_ddn_call, v_cpam_local_call,
     v_cpam_incoming_call, v_cpam_aty_id, 0, v_cpam_lty_id, 0, v_cpam_sys_code_id,
     sysdate, sysdate, 0, trunc(sysdate), trunc(sysdate) + 300, trunc(sysdate) + 300,
     trunc(sysdate) + 300, 'N', 0);
end;

mapper.delete:

declare
  v_owner varchar2(128) := #{owner};
begin
  delete from cellular_number_changes where cnc_clu_cellular = #{cellularNumber};
  delete from prepay_cellulars where pce_clu_cellular_number = #{cellularNumber};
  delete from pp_service_status_hist where psh_clu_cellular_number = #{cellularNumber};
  begin
    execute immediate 'delete from ' || v_owner || '.hubble_interfaces_tmp where hin_cellular_number = :linea' using #{cellularNumber};
  exception
    when others then null;
  end;
end;
